int __cdecl stb_div_eucl(int v1, int v2)
{
    int64_t a = v1;
    int64_t b = v2;
    int q, r;

    // Handle the specific edge cases generated by the compiler to avoid
    // integer overflow when negating INT_MIN (0x80000000).
    if (v1 == 0x80000000 && v2 == 0x80000000) {
        q = 1;
        r = 0;
    } 
    else if (v1 == 0x80000000) {
        if (v2 < 0) {
            // v1 - v2 avoids negating v1. (v1 - v2) / -v2 is mathematically v1 / v2
            q = (int)((b - a) / -b) + 1;
            r = (int)-((b - a) % -b);
        } else {
            // v2 + v1 avoids negating v1. (v2 + v1) / v2 is mathematically v1 / v2
            q = (int)-((b + a) / b) - 1;
            r = (int)-((b + a) % b);
        }
    } 
    else if (v2 == 0x80000000) {
        if (v1 < 0) {
            q = 1;
            r = v1 - v2;
        } else {
            q = 0;
            r = v1;
        }
    } 
    else {
        // Standard truncated division for all other values
        q = (int)(a / b);
        r = (int)(a % b);
    }

    // Adjust to Euclidean division if the remainder is negative
    if (r < 0) {
        if (v2 > 0) {
            q -= 1;
        } else {
            q += 1;
        }
    }

    return q;
}